pub fn npm_package_shim(name: &str) -> Option<&'static str> {
    NPM_PACKAGE_SHIMS
        .binary_search_by_key(&name, |(n, _)| n)
        .ok()
        .map(|i| NPM_PACKAGE_SHIMS[i].1)
}
